// The typed scheme of the replay's image hash (replay.cpp; recordings with kFlagTypedHash): which bytes of the hashed
// .data / .bss hold a pointer, which typed non-pointer data and which untyped bytes, from the types of the data image
// (src/replay/hash_types.inc, generated by re/replay/gen_hash_types.py from src/data/layout.hpp). The hash then
//   - normalises every pointer field (null / an image address as its original address / other pointers a tag: the
//     caller's normaliser, forced_normalise in replay.cpp),
//   - compares typed non-pointer fields as they are (no normalisation, no blanking: a timer or a counter is a number in
//     every run, whatever it looks like in one run's address layout),
//   - leaves the untyped bytes to the old heuristics (pointer positions guessed while recording, replay.cpp classify),
//     which may only use 4-byte windows that lie wholly in untyped bytes.
// A recording carries its table (Env "hash-types\n"), so a replay hashes with the recording's classes even when a later
// build typed more fields. Platform independent (no <windows.h>): re/replay/test_typed_hash.cpp runs it on a host.
#pragma once

#include <cstddef>
#include <cstdint>
#include <string>
#include <vector>

/// The typed scheme of the replay image hash: which bytes of the hashed data hold pointers, typed data or untyped bytes.
namespace joan::replay::typed {

/// Class of one byte of the hashed range.
enum Class : std::uint8_t { kTyped = 0, kPointer = 1, kUntyped = 2 };

/// A run of bytes, as offsets from the start of the hashed range.
struct Span {
    std::uint32_t begin /**< first byte offset from the start of the hashed range */, end /**< one past the last */;
};

/// The typed description of a hashed range: which bytes are pointers and which are not described.
struct Table {
    std::vector<std::uint32_t> pointers;  ///< byte offsets of the 4-byte pointer fields, sorted, not overlapping
    std::vector<Span> untyped;            ///< bytes of no known type, sorted, not overlapping
};

/// This build's table (hash_types.inc) for the range [va, va + size) of original addresses.
Table builtin(std::uint32_t va, std::uint32_t size);

/// The table as the payload of the recording's Env event (after its tag), and back. Returns false on a damaged payload.
std::string serialise(const Table& t);
/// Parses the payload written by serialise() into `out`; false on a damaged payload.
bool deserialise(const std::uint8_t* p, std::size_t n, Table& out);

/// A short fingerprint for reports (two tables with the same one classify the same bytes).
std::uint64_t fingerprint(const Table& t);

/// One Class per byte of a range of `size` bytes (entries outside it are dropped). False when entries overlap or
/// fall outside the range (a damaged table).
bool classes(const Table& t, std::uint32_t size, std::vector<std::uint8_t>& out);

/// The 4-byte window at o lies wholly in untyped bytes (the old heuristics may look at it).
inline bool untyped4(const std::vector<std::uint8_t>& cls, std::uint32_t o) {
    return o + 4 <= cls.size() && cls[o] == kUntyped && cls[o + 1] == kUntyped && cls[o + 2] == kUntyped &&
           cls[o + 3] == kUntyped;
}

/// Writes norm(value) over every pointer field of `dst` (a copy of `image`, `size` bytes); values are read from image.
template <class Normalise>
void normalise_pointers(const Table& t, const std::uint8_t* image, std::uint8_t* dst, std::uint32_t size,
                        Normalise&& norm) {
    for (const std::uint32_t o : t.pointers) {
        if (o + 4 > size) continue;
        const std::uint32_t v = static_cast<std::uint32_t>(image[o]) | static_cast<std::uint32_t>(image[o + 1]) << 8 |
                                static_cast<std::uint32_t>(image[o + 2]) << 16 |
                                static_cast<std::uint32_t>(image[o + 3]) << 24;
        const std::uint32_t n = norm(v);
        dst[o] = static_cast<std::uint8_t>(n);
        dst[o + 1] = static_cast<std::uint8_t>(n >> 8);
        dst[o + 2] = static_cast<std::uint8_t>(n >> 16);
        dst[o + 3] = static_cast<std::uint8_t>(n >> 24);
    }
}

}  // namespace joan::replay::typed
